         starter_code="import heapq\n\nclass Node:\n    def __init__(self, val):\n        self.val = val\n        self.next = None\n\ndef build_list(values):\n    head = None\n    for v in reversed(values):\n        node = Node(v)\n        node.next = head\n        head = node\n    return head\n\ndef to_list(head):\n    result = []\n    while head:\n        result.append(head.val)\n        head = head.next\n    return result\n\ndef merge_k_lists(lists):\n    heads = [build_list(values) for values in lists]\n    # A min-heap holding 'the current front node of each still-active\n    # list' lets you always pull the smallest available value in\n    # O(log k), rather than scanning all k list-fronts every time\n    # (which is what merging lists two-at-a-time in sequence effectively\n    # does, repeatedly).\n    pass\n",
